    state.scenario = value;
    if(value!=='start'&&!state.inquiries.cases.length)state.inquiries=copy(DATA.inquiries);
    if(value!=='start'&&!state.repair.cases.length)state.repair=copy(DATA.repair);
    if(value!=='start'&&!state.letters.letters.length)state.letters=copy(DATA.letters);
    const completed = value === 'completed';
    state.funding.engagement.status = completed ? 'completed' : 'active';
    state.services.engagement = copy(state.funding.engagement);
    state.services.allowance.engagementActive = !completed;
    state.services.capabilities.requestHelp = !completed;
    state.services.capabilities.requestReport = !completed;
    state.inquiries.cases.forEach(c=>{
      c.actions = {canRecordSubmission:!completed,canLaunchCall:!completed,canCheckSavedEvidence:!completed};
      c.inquiries.forEach(i=>{i.state=['ready','completed'].includes(value)?'removed_verified':'pending_verification';i.verifiedAt=['ready','completed'].includes(value)?stamp():null;});
      c.status = ['ready','completed'].includes(value)?'Sample evidence verified':'In progress';
    });
    state.funding.lenders.forEach(l=>{l.available=value==='ready';l.reason=value==='ready'?'Sample evidence stage permits this fictional bank.':completed?'The sample purchased engagement is complete.':'Waiting for the sample bureau evidence review.';});
    state.funding.state = value === 'start' ? 'needs_file' : completed ? 'completed' : value === 'ready' ? 'ready' : 'optimize';
    state.funding.nextAction = value==='start'?'Request the included sample report to begin.':completed?'This sample purchased funding engagement is complete. History remains available.':value==='ready'?'Review the fictional bank application and record a sample response.':'Review the sample repair letters, inquiry case and preparation tasks.';
    state.repair.actions.canGenerate = !completed;
    state.funding.canFinishSubmissions = value==='ready';
    if (value==='start' && fresh) {state.plan.businessPlans.businesses=[];state.plan.businessPlans.startedAt=null;state.plan.businessPlans.setupStep=0;state.plan.businessPlans.hasExistingBusiness=null;state.plan.businessPlans.payoffPlan=null;state.funding.applications=[];state.inquiries.cases=[];state.repair.cases=[];state.repair.program=null;state.repair.actions.canGenerate=false;state.letters.letters=[];state.services.requests=[];}
