    if(value==='ready')for(const business of state.plan.businessPlans.businesses){business.formationStatus='reported_formed';business.formationDate='2025-11-01';business.ownershipSince='2025-11-01';business.operatingSince='2025-12-01';business.evidence={formation:{status:'accepted',documentId:DATA.ids.document,reviewedAt:stamp(),sample:true},ein:{status:'accepted',documentId:DATA.ids.letter,reviewedAt:stamp(),sample:true}};}
